UPDATE employee_assessments SET answers = '{"a1":5,"a2":6,"a3":7,"a4":7,"a5":6,"b2":5,"b3":4,"b4":3,"b5":7,"b6":7,"b7":5,"b8":6,"b9":7,"c1":"Selama 7 bulan berjalan bersama, saya mendapatkan banyak fasilitas jika dibanding dengan pekerjaan sebelumnya, dan sejauh ini jadi benefit baik bagi saya. Aktivitas dan kerjasama yang terjalin juga baik, interaksi masih positif dan suasana kerja cukup fun bagi saya sehingga ini baik untuk kinerja saya pribadi. ","c2":"Meski fun dan santai, namun profesional dalam bekerjasama antar departemen/divisi yang berbeda harus tetap disediakan SOP yang diikuti oleh semua karyawan, sehingga tidak ada kesan overload beban kerja yang seharusnya bukan dari KPI yang kita terima. Karena saya juga orang baru masuk jadi hal-hal yang seharusnya diketahui terkait lembaga dan lainnya, mungkin ada panduan khusus dan pengenalan yang khusus juga. Dan, untuk beberapa kesempatan terkadang ada keputusan2 atau hal2 yang terkesan gantung karena belum update atau belum menerima respon langsung, harapannya entah interaksi dalam/luar divisi","c3":"Training of Trainers (TOT), Public Speaking, Training Needs Analysis, Manajemen SDM, keuangan dasar, manajemen fasilitasi","c4":"agak sedikit jauh dengan performa dan pengalaman yang saya punya, Jika saya ditunjuk sebagai pimpinan, hal yang ingin saya perbaiki adalah arah kerja dan kinerja, memastikan bahkan sampai staf paling junior paham dengan KPI nya, bukan hanya menerka dan sudah menyelesaikan apa yang dikerjakan tanpa tahu achieve atau tidaknya. Saya juga akan memperbaiki budaya komunikasi yang sebenranya terlihat baik karena suasana kantor yang fun, tapi untuk beberapa momen serius hal tersebut jadi agak kurang etis. bukan kaku tapi lebih profesional aja, sehingga pendapat dan lainnya tetap bisa nyaman disampaikan. Saya ingin memaksimal pembangunan perkembangan SDM yang ada, lewat proses yang mendukung. Dengan tujuan agar terciptanya kompetensi yang meningkat pada diri karyawan, sehingga dua tiiga tahun bekerja mereka mendapatkan pengembangan diri yang lebih juga. bagi saya pimpinan bukan hanya sosok yang hanya bertugas memberikan arahan tertentu, namun jadi contoh dalam tanggung jawab dan perkembangan diri.","c5":"hal yang saya lihat sejauh ini adalah evaluasi kinerja atau program dalam tim atau departement, terkadang kesalahan2 yang sama terulang lagi, penguatan evaluasi adalah salah satu hal yang kurang efektif sejauh performa saya 7 bulan ini","c6":"Meningkatkan kualitas komunikasi dan koordinasi, sehingga ngga terkesan dadakan, atau terpaksa mengadakan. Mengevaluasi berkala dan meningkatkan kualitas bertanggung jawab dengan amanahnya untuk setiap karyawan aktif. Adain pelatihan per divisi atau per program selain yang satu divisi, sesuai dengan kebutuhan program. adakan berkala juga gathering fun meski sederhana.","b10":5,"b11":6,"b12":5,"b13":3,"b14":5,"b15":5,"b16":6,"b17":5,"b18":4,"b19":5,"b20":5,"b21":5,"b22":5,"b23":4,"b24":6,"b25":2}' WHERE id = 'c4a16e53-95b4-4a7e-b373-80e23433cbe9';
UPDATE employee_assessments SET answers = '{"a1":2,"a2":3,"a3":1,"a4":1,"a5":3,"b2":2,"b3":5,"b4":3,"b5":4,"b6":5,"b7":5,"b8":5,"b9":5,"c1":"Semua nya baik","c2":"Hc","c3":"Cukup","c4":"Cukup sebagai pelaksana saja","c5":"Proses penilaian ","c6":"Komunikasi yg baik akan berjalan dengan baik","b10":5,"b11":5,"b12":5,"b13":5,"b14":5,"b15":6,"b16":6,"b17":6,"b18":6,"b19":6,"b20":5,"b21":5,"b22":5,"b23":5,"b24":5,"b25":5}' WHERE id = '80b43789-d66f-444d-b1de-f0c10392f5e3';
UPDATE employee_assessments SET answers = '{"a1":6,"a2":6,"a3":6,"a4":6,"a5":7,"b2":7,"b3":5,"b4":1,"b5":6,"b6":7,"b7":6,"b8":6,"b9":6,"c1":"1. Egalitarianism\\n2. Kekeluargaan yg dibangun\\n3. Fleksibilitas\\n4. Dorongan untuk bertumbuh & berkembang","c2":"1. Tempat/ruang kerja\\n2. Kejelasan promosi/rotasi SDM\\n3. Kompensasi & benefit","c3":"Executive leadership, Global philanthropy ecosystem, Institutional transformation, dan Governance & board management","c4":"1. Mengokohkan Arah & mindset kelembagaan\\nNarasi lembaga perlu diperkuat agar tidak terjebak pada bisnis penyedia jasa pendidikan, atau berjalan seperti as usual saja. Perlu titik temu & penyamaan persepsi/cara pandang lembaga sebagai institusi yang menciptakan masyarakat (the creator society) merdeka, bebas, & berdaya.\\n2. Merapikan struktur & tata kelola organisasi\\n3. Setiap stakeholders organisasi fokus pada Impact, tidak terjebak dgn aktivitas.\\n4. Penguatan budaya kelembagaan.","c5":"1. Bottleneck pada 1 orang. Hal ini menyebabkan banyaknya pekerjaan yg hanya bertumpuk pada peran Kepala Organ & Kepala Divisi. Bisa jadi karena adanya trust yg rendah & adanya kecenderungan budaya micromanagement. Hal ini tentu berdampak pada kaderisasi & regenerasi kepemimpinan di organisasi.\\n2. Proses administrasi yg berlebihan. Hal ini ditunjukkan dgn adanya gejala seperti terlalu banyak form, approval berlapis, & birokrasi yg memperlambat kerja.","c6":"1. Tempatkan orang sesuai kapasitas & kapabilitasnya.\\n2. Membangun budaya ownership, misal dengan melibatkan tim dalam pengambilan keputusan, memberi ruang inisiatif, menghindari micromanagement, mengapresiasi kontribusi, dan menjadikan mereka bagian dari misi besar membangun peradaban.\\n3. dll","b10":5,"b11":7,"b12":6,"b13":1,"b14":5,"b15":7,"b16":6,"b17":4,"b18":4,"b19":6,"b20":6,"b21":7,"b22":5,"b23":4,"b24":5,"b25":2}' WHERE id = '114aadf8-86f1-4dbd-b8a1-f3e0f1082c8b';
UPDATE employee_assessments SET answers = '{"a1":6,"a2":6,"a3":6,"a4":7,"a5":7,"b2":7,"b3":6,"b4":3,"b5":7,"b6":6,"b7":6,"b8":7,"b9":6,"c1":"Engagement Tim, Support antar Divisi, Loyalitas tim Teach, Sinergi antar SDM","c2":"Saling terkoneksi antar pekerjaan/Departemen supaya bisa melakukan pekerjaan lebih efektif dan efisien ","c3":"Soft Skill : Leadership, Negoitation,  \nHard skill : AI","c4":"Sinergitas Departemen. Coaching SDM, Mentoring SDM, Mengembangkan Networking, ","c5":"\"Belum ada\"","c6":"Challange, Kompetisi antar SDM, Kompetisi antar Departmen, Training, Coaching ","b10":6,"b11":6,"b12":6,"b13":4,"b14":6,"b15":7,"b16":7,"b17":5,"b18":5,"b19":5,"b20":7,"b21":6,"b22":6,"b23":5,"b24":4,"b25":3}' WHERE id = '11af745b-443c-4bb3-965f-4dd45be2b663';
