UPDATE employee_assessments SET answers = '{"a1":4,"a2":5,"a3":5,"a4":6,"a5":4,"b2":6,"b3":4,"b4":3,"b5":5,"b6":4,"b7":5,"b8":4,"b9":5,"c1":"-","c2":"1. Tujuan dan koordinasi antar tim, TEACH ini adalah bagian dari DD, jangan sampai kita merasa bersaing dengan bagian lain di DD\\n2. karena baru ada staf di YES, saya belum ada KPI, jadi sejauh ini mengerjakan tugas berdasarkan arahan atasan dan/atau inisiatif dengan tetap ada koordinasi dengan atasan","c3":"Pelatihan coaching","c4":"1. administrasi, karena saya melihat banyak orang hebat tapi dibebankan administrasi yang cukup menguras waktu\\n2. managemen sdm sesuai dengan potensi","c5":"-","c6":"-","b10":4,"b11":5,"b12":5,"b13":4,"b14":5,"b15":4,"b16":5,"b17":5,"b18":4,"b19":4,"b20":4,"b21":3,"b22":5,"b23":5,"b24":5,"b25":4}' WHERE id = '884431bc-a440-4a7d-9529-bd2f5db76537';
