UPDATE employee_assessments SET answers = '{"a1":7,"a2":7,"a3":7,"a4":7,"a5":7,"b2":7,"b3":5,"b4":2,"b5":6,"b6":6,"b7":6,"b8":5,"b9":5,"c1":"Hubungan antar karyawan sudah terbangun dengan baik, kesempatan untuk berkembang dan diberi kebebasan untuk berinisiatif dalam menjalankan pekerjaan maupun mencapat target kerja","c2":"Ruang kerja yang masih terpisah di dua lokasi berjauhan, ruang kerja Departemen di RBJ masih satu ruangan besar kurang nyaman untuk aktivitas khusus Departemen.","c3":"Pengembangan Leadership, ","c4":"Kapasitas diri dan upaya untuk mengenal tim satu per satu","c5":"Beberapa proses yang masih manual dalam pengelolaan lembaga. Baik manual yang bersifat hard dokumen maupun online tapi prosesnya masih membutuhkan proses administrasi yang panjang","c6":"Memastikan proses administrasi yang bisa di rubah menjadi online dan terdokumentaasi secara otomatis. Selain itu perlu menggabungkan beberapa aktivitas dalam satu proses sistem informasi atau dapat mengintegrasi beberapa sistem informasi yang ada.","b10":4,"b11":7,"b12":5,"b13":3,"b14":5,"b15":6,"b16":5,"b17":5,"b18":2,"b19":6,"b20":7,"b21":7,"b22":7,"b23":6,"b24":4,"b25":2}' WHERE id = '24c450a3-58dc-4965-9317-5d878a62600a';
UPDATE employee_assessments SET answers = '{"a1":4,"a2":5,"a3":4,"a4":4,"a5":6,"b2":5,"b3":4,"b4":4,"b5":4,"b6":5,"b7":4,"b8":5,"b9":5,"c1":"kordinasi dan kominakasi sesama tim Teach Bagus","c2":"singkronisasi antar program  yang ada di Teach ","c3":"mengadakan Pelatihan Manajeman SDM Teach ","c4":"Membuat Progaram traning SDM secara Rutin dan membuat meeting sesama Program Teach Setiap Sepekan  ","c5":"Tidak Ada","c6":"mengembangan perencanaan program yang sudah di tentukan atau terperinci dan memberikan bimbingan, dukungan dan motivasi kepada individu  atau tim selama proses perbaikan kinerja. ","b10":2,"b11":4,"b12":4,"b13":4,"b14":6,"b15":5,"b16":5,"b17":5,"b18":4,"b19":6,"b20":5,"b21":6,"b22":5,"b23":4,"b24":5,"b25":4}' WHERE id = 'e76782da-547f-4cad-96ea-162ed949eac0';
UPDATE employee_assessments SET answers = '{"a1":6,"a2":7,"a3":7,"a4":7,"a5":7,"b2":7,"b3":5,"b4":6,"b5":7,"b6":6,"b7":6,"b8":6,"b9":6,"c1":"Untuk program sudah berjalan dengan baik,  seleksi YES kali ini didukung penuh oleh tim IT. namun kami dari program perlu dukungan dari tim remo untuk funding dana program YES","c2":"Alur komunikasi dari setiap departemen\\n","c3":"1. Leadership & Team Management\\n2. Self Development & Sustainability\\n3. Partnership Building","c4":"Leadership dan team management ","c5":"Tidak ada\\n","c6":"1. Perkuat Capacity Building Tim\\n2. Tingkatkan Rasa Memiliki (Sense of Belonging)\\n3. Perkuat Kolaborasi dan Jejaring","b10":7,"b11":6,"b12":7,"b13":6,"b14":6,"b15":7,"b16":6,"b17":6,"b18":6,"b19":5,"b20":6,"b21":6,"b22":7,"b23":6,"b24":6,"b25":6}' WHERE id = '459f9ba2-e953-4c6f-91d3-551b8b82b079';
UPDATE employee_assessments SET answers = '{"a1":6,"a2":6,"a3":6,"a4":5,"a5":6,"b2":5,"b3":5,"b4":3,"b5":5,"b6":6,"b7":5,"b8":5,"b9":4,"c1":"pola kepemimpinan, arahan & juga sifat kekeluargaan sehingga termotivasi untuk melakukan pekerjaaan dengan sebaik-baiknya","c2":"kerja tim & saling bantu membantu jika ada permasalahan pekerjaan yang agak sulit dilakukan sendiri","c3":"membuat sistem aplikasi dokumentasi yang sesuai dengan SOP & kebutuhan kedepan","c4":"bekerja dengan sepenuh hati & penuh rasa kekeluargaan agar hasil yang dicapai sesuai dengan visi misi lembaga serta kemaslahatan umat","c5":"Selama ini semua proses berjalan cukup efektif sesuai dengan tujuan & misi lembaga","c6":"bekerja dengan sepenuh hati & juga sesuai dengan jobdesk masing-masing dan sesuai dengan arahan ","b10":5,"b11":5,"b12":5,"b13":3,"b14":6,"b15":5,"b16":5,"b17":6,"b18":4,"b19":5,"b20":5,"b21":5,"b22":5,"b23":4,"b24":4,"b25":4}' WHERE id = 'fce56fdf-ec62-49d1-9749-2c91e5eae0b8';
UPDATE employee_assessments SET answers = '{"a1":4,"a2":4,"a3":5,"a4":4,"a5":4,"b2":4,"b3":5,"b4":3,"b5":4,"b6":5,"b7":4,"b8":4,"b9":4,"c1":"saya  merasa kurang kompeten di posisi saya sekarang","c2":"Jika berkenan saya ingin di pindah oprasional karna di Markom saya merasa tidak bisa bekerja dengan maksimal","c3":".","c4":".","c5":"menempatkan SDM bukan pada bidang pekerjaannya","c6":".","b10":5,"b11":4,"b12":3,"b13":2,"b14":4,"b15":4,"b16":5,"b17":5,"b18":2,"b19":2,"b20":4,"b21":4,"b22":3,"b23":4,"b24":5,"b25":3}' WHERE id = 'c4db4069-adfb-49a6-9b3d-e97d5bdee4ce';
UPDATE employee_assessments SET answers = '{"a1":4,"a2":5,"a3":4,"a4":5,"a5":4,"b2":4,"b3":4,"b4":3,"b5":4,"b6":3,"b7":3,"b8":4,"b9":4,"c1":"all is well, so far so good aja sih, tapi coba senggol atasannya aja ya","c2":"banyak, udah gitu aja","c3":"videografi, desain, fotografi, kehumasan, public speaking","c4":"diri sendiri, bare minimum banget","c5":"kebanyakan rapat tapi yang dibahas sama aja","c6":"saling nauin satu sama lain, gak merasa diri paling baik dari orang lain, di atas langit masih ada Allah Swt.","b10":4,"b11":4,"b12":3,"b13":4,"b14":3,"b15":4,"b16":4,"b17":4,"b18":5,"b19":3,"b20":4,"b21":3,"b22":4,"b23":4,"b24":4,"b25":4}' WHERE id = 'f8a1e07e-7d13-473a-8419-d2a2aa771939';
UPDATE employee_assessments SET answers = '{"a1":5,"a2":7,"a3":5,"a4":6,"a5":5,"b2":5,"b3":4,"b4":3,"b5":7,"b6":6,"b7":7,"b8":5,"b9":6,"c1":"Sebetulnya, pengetahuan dan pengalaman terkait TEACH setelah proses pengerucutan dari GREATEdunesia memang masih terbatas. Hal ini wajar, mengingat transisi organisasi membutuhkan waktu untuk adaptasi. Namun, dari dinamika yang saya rasakan, ada beberapa aspek yang sudah berjalan baik sekaligus membuka ruang refleksi bagi saya. \\nPertama, agenda bonding tim terasa lebih intim dan berkualitas. Dengan cakupan program yang lebih sedikit, interaksi antar anggota menjadi lebih intens dan personal. Hal ini memudahkan proses saling mengenal, membangun keakraban, serta memperkuat rasa kepemilikan terhadap program. Namun, keintiman ini juga perlu diimbangi dengan strategi agar bonding tidak berhenti pada level emosional, melainkan berkembang menjadi kolaborasi produktif lintas program.\\nKedua, fasilitas kantor, khususnya di KSJ, sudah cukup representatif untuk mendukung produktivitas. Ruang kerja yang kondusif memudahkan diskusi antarprogram, menciptakan atmosfer kerja yang lebih profesional, dan membuka peluang untuk inovasi. \\nKetiga, meskipun kolaborasi antar tim belum banyak dicoba, potensi ke arah sana sangat terbuka. Dengan struktur program yang lebih ramping, peluang untuk saling membantu dalam implementasi kegiatan menjadi lebih realistis. Tantangannya adalah bagaimana membangun mekanisme kolaborasi yang jelas, sehingga tidak hanya bergantung pada inisiatif personal, tetapi menjadi bagian dari sistem kerja TEACH.","c2":"Dari sisi subjektif saya beberapa hal yang akan lebih baik jika diperbaiki seperti;\\n1. Menyediakan ruang kerja fleksibel (co-working style) untuk mendukung kolaborasi lintas tim.\\n2. Menambah fasilitas pendukung digital seperti perangkat presentasi, ruang rapat hybrid\\n3. Memberikan benefit tambahan seperti dukungan psikologis atau program keseimbangan kerja-hidup.\\n4. Menyelenggarakan pelatihan ''rutin'' berkala internal seperti workshop, seminar, dll.\\n5. Menambah kuota learning wallet atau bentuk insentif tambahan lainnya hehe\\n\\nSelebihnya sudah saya syukuri keadaannya dan dioptimalkan dengan apa yang sudah ada. ","c3":"Wah, pelatihan dan pengembangan tentu bertujuan untuk meningkatkan dan menjaga produktifitas kinerja karyawan ya. Beberapa materi yang bisa dipertimbangkan seperti;\\n1. Workshop Digital Tools yang relevan dengan konteks pengembangan dan pengelolaan program.\\n2. Pelatihan Work Life Balance & Stress Management, bisa jadi opsi meski nampak sepele tapi bisa dijadikan sebagai momentum untuk berefleksi dan merefresh energi. \\n3. Kegiatan olahraga bersama yang rutin berkala, bisa juga split gender untuk mengingatkan karyan mengenai urgensi kesehatan dalam menunjang produktifitas kerja.\\n4. Training Leadership & Project Management, untuk menutrisi dan menguatkan pemahaman yang dimiliki. \\n5. English Bootcamp for Professional Communication, bukan hanya 1x training. Tapi karyawan yang belum mumpuni dalam skill bahasa asing didukung untuk meningkatkan kompetensinya agar mampu membuka akses ke sumber pengetahuan global dan memperluas jejaring kemitraan di lingkup internasional. Bisa dengan pelatihan intensif dan berkala atau fasilitasi dengan platform digital yang relevan. \\n6. Workshop pengembangan kurikulum program, mirip seperti training MEAL lalu, tapi pendalaman dibagian Plannya. ","c4":"Jika saya ditunjuk menjadi pimpinan dalam ruang lingkup entitas pendidikan, maka langkah pertama yang harus dipastikan adalah bahwa nilai dan tujuan entitas yang saya pimpin tidak bertentangan dengan norma dan nilai agama. Hal ini menjadi pondasi moral sekaligus arah kompas bagi setiap kebijakan. Namun, memastikan kesesuaian nilai saja tidak cukup, perlu ada keberanian untuk mengkritisi aspek-aspek yang selama ini berjalan tanpa evaluasi mendalam.\\nLangkah berikutnya adalah mempelajari seluruh aspek yang melingkupi entitas: sistem, SDM, sejarah, hingga praktik baik (best practice) maupun praktik buruk (bad practice) yang pernah terjadi. Pendekatan ini penting agar kebijakan tidak hanya berbasis idealisme, tetapi juga grounded pada realitas dan pengalaman masa lalu. Tantangannya adalah bagaimana menyelaraskan semua itu dengan kondisi hari ini yang terus berubah.\\n\\nDalam konteks daya dukung, SDM adalah faktor utama. Kualitas SDM bukan hanya soal kompetensi teknis, tetapi juga penempatan yang tepat, pengelolaan konflik internal maupun eksternal, serta penciptaan kenyamanan bagi semua pihak, bukan hanya segelintir orang. Kritik yang perlu diajukan adalah bahwa banyak organisasi pendidikan gagal karena tidak mampu menempatkan SDM sesuai kapasitasnya, sehingga potensi besar justru terhambat oleh birokrasi atau konflik kepentingan.\\nSelain itu, sistem komunikasi dan birokrasi sering kali dianggap masalah kecil, padahal dampaknya bisa sangat besar. Komunikasi yang keliru dan birokrasi yang rumit dapat melumpuhkan efektivitas organisasi. Perbaikan di sini bukan sekadar menyederhanakan alur, tetapi membangun budaya komunikasi yang jujur, terbuka, dan solutif.\\n\\nSelanjutnya, business process harus berjalan efektif dan efisien tanpa “mendzolimi” pihak manapun. Artinya, setiap kebijakan harus mempertimbangkan keadilan, transparansi, dan dampak jangka panjang. Kritik yang perlu ditegaskan adalah bahwa efisiensi sering kali dijadikan alasan untuk mengorbankan hak-hak tertentu, padahal efisiensi sejati adalah ketika semua pihak merasa dihargai.\\nLangkah-langkah umum seperti monitoring dan evaluasi berkala tetap penting, tetapi harus dilakukan dengan pendekatan yang lebih kritis: bukan sekadar menilai capaian angka, melainkan juga menilai integritas, budaya kerja, dan keteladanan. Integritas harus menjadi teladan yang membudaya, bukan jargon yang hanya muncul di laporan tahunan. Wallahualambisawab","c5":"Saya yakin sudah banyak hal baik yang sudah diupayak. Namun untuk melejitkan kualitas lembaga, berdasar subjektif saya beberapa hal ini bisa menjadi masukan;\\n1. Perubahan Sistem Tanpa Penjelasan\\nPerubahan sistem sering dilakukan tanpa alasan yang jelas, sehingga tim harus berulang kali beradaptasi. Contoh sederhana adalah perubahan desi atau alur kerja yang tidak disertai penjelasan sebabnya. Hal ini menimbulkan kebingungan, memperlambat produktivitas, dan membuat energi tim terkuras untuk menyesuaikan diri, bukan untuk berinovasi.\\n2. Overlapping Tugas SDM\\nPengelola program sering kali harus merangkap tugas lain seperti marketing, konten media, pengelolaan alumni, hingga kemitraan. Kondisi ini semakin berat karena jumlah SDM dikurangi atas nama efisiensi. Akibatnya, kualitas kerja menurun, fokus program terpecah, dan potensi burnout meningkat.\\n3. Pembatasan Extend Perjalanan Dinas\\nKebijakan yang membatasi extend perjalanan dinas juga terasa tidak efektif. Padahal, memperpanjang beberapa hari dengan biaya pribadi bisa menjadi momentum untuk refresh energi dan release emosi. Jika tiket tetap sesuai aturan perdin, memberi izin cuti tambahan seharusnya tidak menjadi masalah.\\n4. Penginputan Learning Hours\\nProses penginputan learning hours belum jelas tindak lanjutnya. Apakah data tersebut digunakan untuk meningkatkan saldo learning wallet atau ada konteks lain? Karena tidak ada kejelasan, banyak karyawan jarang mengisi. Esensi dari learning hours pun hilang, hanya menjadi formalitas administratif.\\n5. Informasi Skema & Kebijakan\\nInformasi mengenai skema atau kebijakan sering tidak detail dan tidak terkondisikan dengan baik. Perubahan alur operasional atau kebijakan strategis (misalnya perubahan jabatan/fungsi SDM) tidak selalu disampaikan secara umum, sehingga menimbulkan revisi berulang dan salah konsolidasi.\\n6. Evaluasi yang Tidak Ditindaklanjuti\\nEvaluasi program, operasional, maupun pengelolaan memang rutin dilakukan setiap tahun. Namun, hasil evaluasi jarang ditindaklanjuti secara signifikan. Akibatnya, evaluasi hanya menjadi ritual, bukan alat perbaikan. Hal ini menimbulkan rasa skeptis di kalangan karyawan, karena masukan mereka tidak terlihat dampaknya.","c6":"1. Peningkatan kinerja tim dan organisasi menuntut perbaikan sistem yang transparan, penataan ulang SDM agar tidak terbebani tugas berlapis, serta kebijakan kesejahteraan yang lebih membahagiakan. \\n2. Peningkatan kompetensi SDM sebagai investasi lembaga perlu dimasifkan agar mereka produktif dan expert dalam menjalani perannya. \\n3. Komunikasi dan birokrasi harus disederhanakan, bukan hanya efisiensi SDM namun alur sistem birokrasi pun termasuk didalmnya.\\n4. Evaluasi yang ditindaklanjuti secara nyata. \\n5. Bonding tim harus tetap lestari dan berkembang menjadi kolaborasi produktif. \\nDengan langkah ini, semoga tidak hanya lebih efisien, tetapi juga lebih sehat, adaptif, dan berdaya saing.","b10":4,"b11":5,"b12":5,"b13":4,"b14":5,"b15":5,"b16":4,"b17":4,"b18":4,"b19":5,"b20":6,"b21":5,"b22":6,"b23":4,"b24":6,"b25":5}' WHERE id = '09d19b16-067b-487e-8ed8-84036dfa5e9f';
UPDATE employee_assessments SET answers = '{"a1":4,"a2":6,"a3":6,"a4":5,"a5":5,"b2":4,"b3":4,"b4":4,"b5":7,"b6":5,"b7":5,"b8":4,"b9":6,"c1":"Dengan berada di Teach menjadikan saya terpacu untuk lebih berkembang, insiatif untuk bertanya , memperluas kemampuan dalam mengambil keputusan atau saran- saran untuk teman-teman yang memegang anggaran, mendapat ilmu baru dari DESI 2.0. Karena selama 10 tahun berkarir baru sekarang merasakan apa itu kebebasan berpendapat mengenai apa yang saya kerjakan. Jujur saya lebih suka versi saya yang sekarang dalam bekerja karena saya merasa ini versi terbaik saya namun perlu di asah untuk kemampuan lainnya yang menunjang pekerjaan. Gomawo TEACH","c2":"Kejelasan SKI dan Uraian Jabatan Keuangan di Teach mungkin ya, karena selama ini masih menggunakan yang dari Holding. ","c3":"Tools : Excel Medium \\nPengetahuan : Keuangan sesuai dengan PSAK yang lembaga pakai ( mungkin ) and then Perpajakan.","c4":"SKI , SOP yg detail agar rekan - rekan saling mengerti apa yang dikerjakan, agar rekan - rekan saya tidak timpah tindih dalam pekerjaannya, mencoba juga masuk ke dalam pov para rekan kerja agar semuanya berjalan selaras dan tidak ada karyawan merasa burning out. Inginnya menciptakan lingkungan yang santai terkendali, karena kalau tidak ada kejelasan SKI atau SOP itu awal mula karyawan menjadi burning out.","c5":"Koordinasi dan konfirmasi antara pihak-pihak terkait. ","c6":"Lebih banyak ngobrol untuk menyamakan pov mungkin ya.  Tapi saya sangat merasa dihargai karena ketika awal masuk Teach langsung di ajak ngobrol oleh Bapak Haryo selaku ketua di Teach. saya harap para atasan yang di bawahnya pak Haryo juga sama - sama mengikuti cara beliau ke bawahannya, sekedar menyamakan pov saja. ","b10":6,"b11":5,"b12":6,"b13":4,"b14":6,"b15":4,"b16":7,"b17":5,"b18":4,"b19":5,"b20":7,"b21":5,"b22":6,"b23":6,"b24":4,"b25":3}' WHERE id = '55e6d567-f501-4ae1-bfe9-5f3952e1784d';
UPDATE employee_assessments SET answers = '{"a1":6,"a2":7,"a3":7,"a4":7,"a5":4,"b2":6,"b3":4,"b4":1,"b5":6,"b6":5,"b7":7,"b8":4,"b9":6,"c1":"solidaritas dalam tim","c2":"sistem dan manajemen ","c3":"digital dan Ads","c4":"yang pasti berusaha untuk memataskan diri, memanagemen waktu yang baik berusaha memerikan job dan alur yang jelas pada tim menjadi tempat yang nyaman untuk berdiskusi dengan tim dan mencari solusi terbaik bagi tim dan membagun kemistri agar selalu solid","c5":"saai ini belum ada job yang pasti, menunggu duduk bareng tapi blm dapat kabar lagi yang tiba\" langsung isi penilaian ","c6":"duduk bareng melakukan diskusi dan perencanaan yang jelas, melakukan deep talk dan memberi pencerahan yg sama\" bisa di toleransi bersama","b10":4,"b11":4,"b12":7,"b13":6,"b14":4,"b15":4,"b16":6,"b17":5,"b18":5,"b19":4,"b20":5,"b21":4,"b22":5,"b23":6,"b24":6,"b25":6}' WHERE id = '169542bb-519e-400e-883a-56200feaa5d1';
UPDATE employee_assessments SET answers = '{"a1":5,"a2":5,"a3":5,"a4":5,"a5":4,"b2":5,"b3":5,"b4":2,"b5":6,"b6":5,"b7":5,"b8":4,"b9":4,"c1":"Lingkungan yang positif dan saling support satu sama lain, kekeluargaan, dan kerja sama yang baik ","c2":"Mungkin karena masih baru berdiri menjadi organ sendiri masih banyak alur yang membingungkan dan SOP yang belum jelas terutama dalam hal kemitraan dan penghimpunan","c3":"Marketing, Public Speaking, English for work, Monev, Critical Thinking, ","c4":"Alur dan SOP ","c5":"Proses menunggu approval manager dan dilempar ke yang lain (holding ataupun departemen lain) untuk memulai sebuah project atau inisiasi.","c6":"Untuk tim departemen Remo khususnya di bagian FundComm saya merasa bahwa ada kegamangan atau kebingungan dalam menjalankan arah gerak, kami seperti dilepas di dalam hutan tanpa diberikan sebuah peta dan tujuan arah kemana akan sampai, kami dipersilahkan untuk menggunakan alat-alat disekitar hutan, namun tidak diberi tau cara menggunakannya. Menurut saya kami masih memerlukan peta dan arah tujuan yang clear bersama sebagai tim.","b10":3,"b11":4,"b12":4,"b13":4,"b14":3,"b15":4,"b16":5,"b17":4,"b18":6,"b19":4,"b20":4,"b21":4,"b22":5,"b23":4,"b24":4,"b25":6}' WHERE id = 'f307b5bd-0ee2-487a-abbd-d471640a224a';
UPDATE employee_assessments SET answers = '{"a1":6,"a2":7,"a3":6,"a4":6,"a5":5,"b2":7,"b3":3,"b4":2,"b5":6,"b6":5,"b7":5,"b8":5,"b9":5,"c1":"1. Setiap orang diberi kesempatan untuk mengaktualisasikan diri.\\n2. Egaliter\\n3. Ada agenda untuk menguatkan engagement tim","c2":"1. Penguatan value secara berkala agar kita senantiasa memahami bahwa kita tidak sekadar bekerja.\\n2. Sistem kekaryawanan (rekrutmen, rotasi, promosi) perlu dibuat SOP yang jelas dan berlaku untuk semua.\\n3. Ada standardisasi penyusunan SKI.\\n4. Asesmen beban kerja serta tindak lanjutnya.\\n5. Perlu ada tim yang memiliki kapasitas memadai yang fokus pada membangun kemitraan/kerja sama dengan eksternal. \\n6. Perlu ada forum bersama (diskusi produktif) yang dilaksanakan secara rutin untuk membahas apa yang sedang dan akan kita lakukan, serta membahas isu-isu yang ada.\\n7. Penguatan budaya disiplin (misalnya disiplin waktu kerja dan waktu sholat).","c3":"1. Tentang pemberdayaan masyarakat, dari perencanaan-implementasi-evaluasi. \\n2. Pelatihan menulis opini/artikel serta bagaimana bisa tembus ke media nasional.","c4":"1. Sistem kekaryawanan: kamus kompetensi yang jelas sehingga saat rekrut/rotasi/promosi karyawan; membuat standardisasi SKI sehingga jobdes setiap karyawan tepat dan adil.\\n2. Membuat forum diskusi rutin (misal sebulan sekali) sebagai wadah untuk menajamkan kembali pemikiran dan arah kerja kita, agar tidak sekadar menyelesaikan rutinitas pekerjaan.\\n3. Membuat blue print/arah gerak lembaga yang akan menjadi patokan setiap karyawan dalam menjalankan peran/program, agar setiap apa yang kita lakukan mengarah pada tujuan yang sama.\\n4. Berinventasi besar pada aspek kemitraan eksternal agar lembaga tidak bekerja sendiri dan membiayai program sendiri.\\n5. Audit program bukan sekadar melihat kesesuaian admnisitrasi, tapi juga tentang perbaikan program. Ini bisa juga dilakukan saat Management review, fokusnya adalah pada hal-hal yang substansi terkait program/lembaga.","c5":"Sejujurnya saya belum terlalu memahami pertanyaan ini, masih kurang spesifik. Jadi mohon dimaklumi jika persepsi saya salah.\\nProses yang menurut saya tidak efektif adalah yang dilaksanakan satu arah (tidak melibatkan banyak pihak). Misalnya kebijakan top down tanpa mengakomodir pendapat tim. selain itu juga terkait kebijakan yang dilakukan tanpa pertimbangan yang matang (tergesa-gesa), yang akhirnya akan cepat berubah/berganti. ","c6":"1. Asesmen beban kerja karyawan dan benar-benar ditindaklanjuti. \\n2. Membangun budaya disiplin. Agak berat di awal, tapi jika sudah menjadi kebiasaan hasilnya akan optimal.\\n3. Sistem reward bagi karyawan yang memiliki capaian melebihi target/tugas yang diberikan.\\n4. Apakah memungkinkan ada hari untuk kerja dari mana saja (WFA)?","b10":3,"b11":7,"b12":4,"b13":2,"b14":2,"b15":4,"b16":5,"b17":2,"b18":4,"b19":6,"b20":7,"b21":5,"b22":4,"b23":2,"b24":2,"b25":3}' WHERE id = '08af2dfb-ac05-43f7-9521-b8d09d9faf16';
UPDATE employee_assessments SET answers = '{"a1":6,"a2":1,"a3":2,"a4":7,"a5":7,"b2":7,"b3":5,"b4":1,"b5":7,"b6":7,"b7":7,"b8":5,"b9":6,"c1":"Kekompakan tim program oke","c2":"Saran, Masukan atau kritikan dari atasan kepada bawahan saya sebagai pribadi sangat menantikan ","c3":"Pelatihan praktis yang bisa digunakan menghadapi masa pensiun","c4":"manajemen waktu yg mungkin blm efektif","c5":"blm menemukan","c6":"Apresiasi dari atasan yg tdk perlu berupa uang atau benda sdh cukup jadi penyemangat dalam bekerja, krn itu terasa sangat mahal dan langka di TEACH","b10":7,"b11":7,"b12":7,"b13":4,"b14":7,"b15":7,"b16":7,"b17":5,"b18":5,"b19":7,"b20":6,"b21":7,"b22":7,"b23":7,"b24":6,"b25":7}' WHERE id = '5d730fd0-a15c-48be-ae42-55f2f9f11bb6';
UPDATE employee_assessments SET answers = '{"a1":5,"a2":5,"a3":5,"a4":6,"a5":5,"b2":4,"b3":5,"b4":4,"b5":6,"b6":6,"b7":5,"b8":5,"b9":5,"c1":"1. Program-program semakin berjalan baik, tersistem dan up to date.\\n2. Sudah mulai tersistemasi.\\n3. Kerekatan karyawan sudah mulai terbentuk lagi pasca transformasi.\\n4. Banyak kegiatan yang lebih mudah dihidupkan baik baru maupun sudah ada.\\n","c2":"1. Controlling terhadap karyawan terkait pekerjaan.\\n2. Controlling aset TEACH.\\n3. Pembagian jobdesc yang jelas.\\n4. Perhatian dari atasan ke masing2 bawahan.","c3":"Pelatihan ke SDM-an, walau basic saya dari manajemen, namun belum terlalu dalam memahami manajemen SDM, maka dari itu saya perlu pengembangan apapun terkait ke SDM-an.","c4":"Mendengarkan dan memahami kondisi tim.\\nSaya akan banyak berdiskusi untuk mengetahui tantangan, potensi, dan kebutuhan anggota tim.\\nMenentukan tujuan yang jelas.\\nTim perlu tahu arah kerja dan target yang ingin dicapai agar semua bisa berjalan selaras.\\nMembangun komunikasi yang terbuka.\\nSaya ingin menciptakan suasana kerja yang nyaman untuk menyampaikan ide, masukan, maupun kendala.\\nMemberi contoh yang baik.\\nPemimpin harus bisa jadi teladan dalam disiplin, tanggung jawab, dan sikap kerja.\\nMendukung pengembangan anggota tim.\\nSaya akan mendorong setiap anggota untuk berkembang sesuai kemampuan dan potensinya.\\nMengambil keputusan secara adil dan bijak.\\nDalam setiap keputusan, saya akan mempertimbangkan kepentingan bersama dan mencari solusi terbaik.","c5":"1. Alur approval yang berbelit.\\n2. Pembagian tugas yang tidak sesuai kapasitas, ketika jobdesk tidak jelas atau beban kerja tidak merata, proses kerja jadi tidak efisien dan berpotensi menurunkan motivasi tim.\\n3. Ruangan yang terlalu terbuka dan sangat luas.","c6":"1. Memperjelas target dan pembagian tugas\\n2. Membangun komunikasi yang terbuka (diskusi rutin, sharing ide, dan evaluasi agar anggota tim merasa didengar dan lebih nyaman bekerja sama).\\n3. Memberikan apresiasi atas pencapaian (ucapan terima kasih, poster, feedback positif, atau reward kecil).\\n4. Mengadakan team building\\n5. Nonton bareng/makan bareng.\\n6. Evaluasi SOP atau alur kerja yang terlalu panjang agar pekerjaan bisa lebih cepat dan efisien.\\n7. Tidak membatasi pengembangan diri.\\n8. Training, mentoring, atau sharing session dapat membantu anggota tim meningkatkan skill dan rasa percaya diri.\\n9. Membiasakan evaluasi dan solusi bersama.\\n10. Saat ada kendala, fokus pada mencari solusi dan perbaikan bersama, bukan saling menyalahkan.\\n\\nKarena menurut saya, tim yang produktif bukan hanya soal individu yang hebat, tetapi juga tentang kerja sama, komunikasi, dan lingkungan kerja yang sehat.","b10":5,"b11":5,"b12":6,"b13":6,"b14":4,"b15":4,"b16":4,"b17":5,"b18":5,"b19":5,"b20":5,"b21":6,"b22":5,"b23":5,"b24":5,"b25":5}' WHERE id = '79792d41-c959-4378-ada3-143c7b72b60a';
UPDATE employee_assessments SET answers = '{"a1":5,"a2":7,"a3":7,"a4":7,"a5":5,"b2":6,"b3":5,"b4":5,"b5":7,"b6":7,"b7":5,"b8":7,"b9":7,"c1":"Saya belum menemukan hal yang dpt saya katakan berjalan dg baik, krena bbrp hal yg dinilai baik saat ini hanya dalam bentuk event bukan sesuatu yang berdampak pada organisasi seperti sistem dan kebijakan.","c2":"1. Sistem dan kebijakan \\n2. Alur koordinasi\\n3. Budaya refleksi dan apresiasi \\n","c3":"1. Development program \\n2. Mengukur dampak program\\n\\n","c4":"1. Budaya kerja ; refleksi & apresiasi \\n2. Sistem & alur koordinasi lebih clear dan terbuka \\n3. Kebijakan yang berkeadilan bagi karyawan termasuk pembayaran gaji dan jam kerja ","c5":"Pengambilan kebijakan, byk hal yang kadang miss dan tidak teinformasikan kepada kami sbg staff atau bawahan. Sesederhana perubahan alur pembuatan laporan dan kebijakan-kebijakan baru di keuangan tidak tersampaikan krena tidak adanya forum. \\n","c6":"Biasakan budaya apresiasi & refleksi 2 arah (atasan - bawahan)","b10":4,"b11":7,"b12":5,"b13":7,"b14":4,"b15":7,"b16":7,"b17":4,"b18":7,"b19":5,"b20":5,"b21":5,"b22":7,"b23":4,"b24":3,"b25":7}' WHERE id = '36f39319-9749-4eba-b1d9-43e2763b52ca';
UPDATE employee_assessments SET answers = '{"a1":4,"a2":6,"a3":6,"a4":7,"a5":7,"b2":4,"b3":4,"b4":3,"b5":5,"b6":5,"b7":5,"b8":4,"b9":5,"c1":"mulai lancar di bagian admin keuangan dan operational","c2":"kejelasan jobdesk","c3":"administrasi","c4":"sistem komunikasi dan koordinasi tim dalam memahami tugas yang jelas","c5":"mungkin komunikasi dan koordinasi","c6":"balik ke jawaban pertanyaan esai sebelumnya kaka. terimakasih","b10":4,"b11":5,"b12":6,"b13":4,"b14":4,"b15":5,"b16":5,"b17":4,"b18":5,"b19":5,"b20":5,"b21":5,"b22":5,"b23":5,"b24":4,"b25":6}' WHERE id = 'eb5bf75e-7f68-43d8-8bb4-badc2d06bbcd';
UPDATE employee_assessments SET answers = '{"a1":4,"a2":4,"a3":4,"a4":4,"a5":5,"b2":4,"b3":7,"b4":4,"b5":4,"b6":4,"b7":4,"b8":4,"b9":4,"c1":"kekerabatan","c2":"tempat kerja","c3":"menyelesaikan kuliah","c4":"Sudah tidak terlalu tertarik membahas ini","c5":"Kerja / Program berbasis GOALS atau Dampak","c6":"Peta Karier teman-teman saya","b10":7,"b11":4,"b12":4,"b13":4,"b14":4,"b15":4,"b16":4,"b17":4,"b18":4,"b19":4,"b20":4,"b21":4,"b22":4,"b23":4,"b24":7,"b25":4}' WHERE id = 'a5b7d991-e8d9-4581-9cfe-670b24f117b4';
UPDATE employee_assessments SET answers = '{"a1":5,"a2":6,"a3":6,"a4":6,"a5":5,"b2":2,"b3":2,"b4":1,"b5":6,"b6":7,"b7":6,"b8":5,"b9":6,"c1":"Sepengalaman saya bekerja kurang dari 1 tahun yang sudah baik di TEACH yaitu budaya positif, komunikasi sopan, dan semangat belajar.","c2":"Yang perlu diperbaiki adalah keadilan dalam pembagian tugas serta penyamaan persepsi antar anggota, sehingga tidak terjadi perbedaan persepsi dan tidak ada pihak yang menerima beban pekerjaan terlalu banyak maupun terlalu sedikit.","c3":"Pelatihan Bahasa Inggris (Speaking)","c4":"1. Memperbaiki Sistem manajemen\\n2. Uraian tugas masing-masing anggota jelas dan diketahui semua orang\\n3. Penyamaan tujuan bersama dan komitmen mencapainya\\n4. Monitoring awal, tengah, dan akhir\\n5. Evaluasi yang sustainable","c5":"Proses keterlibatan antar program dan holding/departemen lain.","c6":"Penyamaan persepsi masing-masing tugas ","b10":3,"b11":6,"b12":7,"b13":4,"b14":5,"b15":5,"b16":7,"b17":2,"b18":4,"b19":5,"b20":5,"b21":6,"b22":5,"b23":5,"b24":1,"b25":2}' WHERE id = '13ea71cd-4273-491f-a36c-3d3abb4f54ec';
UPDATE employee_assessments SET answers = '{"a1":6,"a2":6,"a3":6,"a4":7,"a5":6,"b2":5,"b3":5,"b4":3,"b5":6,"b6":6,"b7":7,"b8":6,"b9":7,"c1":"Menurut saya, hal yang sudah berjalan baik di TEACH adalah komitmen dalam mendampingi dan menjalankan program pembinaan bagi para penerima manfaat program beasiswa khususnya diprogram BAKTI NUSA yang saat ini dikelola. Meskipun setiap departemen memiliki tantangan dan tanggung jawab masing-masing, terdapat semangat untuk saling membantu dan mendukung demi tercapainya tujuan program bersama. Apalagi dengan adanya aktivitas kebersamaan yang selama ini diadakan, menurut saya hal tersebut menjadi salah satu hal positif di lingkungan kerja TEACH. Selain bisa menjadi sarana untuk recharging semangat dalam bekerja, kegiatan tersebut juga membantu antar anggota/karyawan untuk saling mengenal lebih dekat, membangun kedekatan, serta mempererat kebersamaan dalam tim.\\n\\nDari sisi pelaksanaan program, kegiatan pembinaan, pendampingan, dan pengembangan kapasitas awardee juga sudah berjalan cukup baik dan memberikan dampak positif bagi awardee, penerima manfaar dileadership projectnya maupun output yang diharapkan program. Tidak hanya dalam aspek akademik, tetapi juga dalam pembentukan karakter, kepemimpinan, dan kepedulian sosial.\\n\\nMenurut saya, nilai kebermanfaatan, kepedulian, dan semangat kontribusi yang dibangun di TEACH juga menjadi hal positif yang membuat program terus berjalan hingga saat ini.","c2":"Menurut saya, hal yang masih perlu diperbaiki di TEACH adalah cara komunikasi dalam bekerja, terutama dalam penggunaan kata-kata dan penyampaian yang lebih nyaman, tidak terkesan mengintimidasi, serta tetap saling menghargai satu sama lain. Selain itu, penting juga untuk tetap menjaga batas privasi pribadi setiap anggota tim agar lingkungan kerja dapat terasa lebih sehat, aman, dan suportif bagi semua. Di sisi lain, pengelolaan beban kerja dan pengembangan kapasitas SDM juga penting untuk terus diperhatikan agar setiap anggota tim dapat bekerja lebih optimal dan tetap berkembang dalam menjalankan perannya masing-masing.","c3":"Pelatihan atau pengembangan yang saya butuhkan saat ini adalah terkait mentoring, coaching, dan pendampingan leadership project agar dapat lebih efektif dalam mendampingi awardee dengan karakter dan tantangan yang beragam. Selain itu, saya juga membutuhkan pengembangan kemampuan dalam problem solving, komunikasi interpersonal, dan conflict handling untuk membantu menghadapi berbagai case yang muncul di lapangan. Di sisi lain, pengembangan keterampilan desain publikasi dan penggunaan tools digital juga akan sangat membantu dalam mendukung kebutuhan pekerjaan program.","c4":"Jika saya ditunjuk sebagai pimpinan, hal yang ingin saya perbaiki adalah membangun komunikasi kerja yang lebih sehat dan saling menghargai, sehingga setiap anggota tim dapat merasa nyaman dalam bekerja dan menyampaikan pendapat. Selain itu, saya juga ingin memperkuat koordinasi dan dukungan antar tim agar pekerjaan dapat berjalan lebih efektif dan kolaboratif.\\n\\nDi sisi lain, saya ingin menciptakan lingkungan kerja yang tidak hanya berorientasi pada target, tetapi juga tetap memperhatikan pengembangan, kenyamanan, dan kesejahteraan anggota tim dalam menjalankan perannya masing-masing.","c5":"Menurut saya, proses yang terkadang masih kurang efektif adalah koordinasi dan alur komunikasi antar bagian, terutama ketika informasi atau perubahan belum tersampaikan secara merata. Hal tersebut kadang membuat pekerjaan menjadi kurang sinkron dan misskomunikasi. misalnya kebijakan keuangan dalam pelaksanaan perjalanan dinas, dll. Serta klasterisasi penggunaan plafon penginapan yang menurut saya itu tidak perlu dibedakan, karena pekerjaan dilapangan juga sama, selain itu bisa hemat anggaran. ","c6":"Menurut saya, salah satu hal yang dapat membantu meningkatkan kinerja tim/organisasi adalah penguatan komunikasi dan koordinasi antar bagian agar informasi dapat tersampaikan lebih jelas dan pekerjaan berjalan lebih sinkron. Selain itu, adanya evaluasi rutin dan ruang diskusi yang sehat juga dapat membantu tim menyampaikan kendala maupun masukan secara lebih terbuka.\\n\\nDi sisi lain, kegiatan pengembangan kapasitas SDM serta aktivitas kebersamaan tim juga penting untuk menjaga semangat kerja, kekompakan, dan rasa saling mendukung antar anggota.","b10":4,"b11":6,"b12":5,"b13":3,"b14":4,"b15":6,"b16":7,"b17":5,"b18":3,"b19":5,"b20":7,"b21":6,"b22":6,"b23":3,"b24":4,"b25":2}' WHERE id = 'e255d26c-054e-4377-bf9e-f395a50ba51e';
UPDATE employee_assessments SET answers = '{"a1":3,"a2":6,"a3":6,"a4":6,"a5":4,"b2":5,"b3":3,"b4":3,"b5":5,"b6":4,"b7":4,"b8":5,"b9":5,"c1":"Manajemen organisasi, budaya kerja, dan hubungan antar individu","c2":"Kejelasan peran dan kontribusi antar departemen agar semua merasa memiliki kontribusi yang nyata","c3":"Pelatihan dan pengembangan dibidang riset seperti menggunakan software statistik dan pelatihan penulisan policy brief yang benar","c4":"Tugas dan tanggung jawab masing-masing departemen dan memberikan kejelasan tugas dan tanggung jawab masing-masing individu, mendorong setiap anggota tim untuk berkembang dan merasa sudah memberikan kontribusi yang nyata terhadap TEACH. ","c5":"Pengembangan dan pelatihan. Masing-masing individu harus berinisiatif sendiri untuk mengembangkan diri dan menggunakan fasilitas serta biaya sendiri. Karena kalau nunggu lembaga prosesnya cukup lama. ","c6":"Meningkatkan rasa self of belonging setiap tim agar semua merasa memiliki TEACH dan berkontribusi penuh di TEACH","b10":4,"b11":4,"b12":5,"b13":6,"b14":5,"b15":5,"b16":5,"b17":4,"b18":4,"b19":5,"b20":4,"b21":4,"b22":5,"b23":6,"b24":4,"b25":6}' WHERE id = '78727b63-c05a-4dfe-8eba-7d7a2d06ede6';
UPDATE employee_assessments SET answers = '{"a1":7,"a2":7,"a3":7,"a4":7,"a5":7,"b2":5,"b3":5,"b4":1,"b5":7,"b6":7,"b7":7,"b8":4,"b9":7,"c1":"1. SLA Keuangan sejauh ini telah berjalan cukup baik. Proses pengajuan menjadi lebih cepat karena pengelolaannya dikendalikan langsung oleh masing-masing organ.\n2. TEACH berhasil membangun ekosistem antar Departemen yang memiliki bonding kuat. Hal ini terlihat dari adanya berbagai kegiatan bersama yang mampu mempererat hubungan dan kolaborasi antar insan TEACH, seperti senam bersama dan aktivitas kebersamaan lainnya.","c2":"1. Perlu adanya pendalaman nilai-nilai (values) TEACH/GREAT Edunesia maupun Dompet Dhuafa kepada seluruh insan TEACH, sehingga nilai tersebut tidak hanya dipahami sebagai pengetahuan, tetapi juga diimplementasikan dalam sikap dan tindakan sehari-hari.\n2. Dengan terpisahnya gedung/ruang kerja antar karyawan TEACH itu sendiri, menyebabkan beberapa koordinasi yang perlu \"CEPAT\" sedikit terhambat.\n3. TEACH perlu melakukan pemetaan untuk pengembangan Karyawan.\n","c3":"1. Memperpanjang program Certified Design Thinking beserta pengembangan kompetensi lanjutan agar implementasi ilmunya lebih optimal.\n2. Mengikuti pelatihan terkait Community Development profesional untuk memperkuat kapasitas pendampingan program social project terhadap PM.\n3. Mengikuti program sertifikasi Coaching guna meningkatkan kemampuan pengembangan individu dan tim.","c4":"1. Melakukan asesmen Work Life Analysis (WLA) pada setiap individu untuk memahami keseimbangan kerja, potensi, dan kebutuhan pengembangan karyawan serta menindaklajuti hasilnya.\n2. Membuat profiling karyawan berdasarkan kompetensi dan keunggulan masing-masing, kemudian mendorong mereka menjadi figur atau pakar di bidangnya.\n3. Membuka lebih banyak ruang aktualisasi agar setiap insan TEACH memiliki kesempatan untuk berkembang, berprestasi, dan menunjukkan potensi terbaiknya.\n4. Monitoring & Evaluasi Departemen per Triwulan agar memahami kendala yang dihadapi disetiap departemen, serta mencari peluang untuk pengembangan.","c5":"- Proses penilaian 360, yang sampai saat ini saya belum mengetahui fungsinya untuk apa.\n","c6":"Menerapkan sistem Reward and Punishment yang jelas dan disepakati bersama oleh masing-masing Insan TEACH sebagai bentuk apresiasi sekaligus penguatan budaya disiplin dan profesionalisme.","b10":5,"b11":7,"b12":7,"b13":4,"b14":6,"b15":5,"b16":7,"b17":4,"b18":4,"b19":6,"b20":6,"b21":6,"b22":5,"b23":5,"b24":5,"b25":1}' WHERE id = '1b57ab09-38d4-4c65-8fd3-9b624ccb4c22';
UPDATE employee_assessments SET answers = '{"a1":5,"a2":7,"a3":7,"a4":7,"a5":7,"b2":5,"b3":5,"b4":1,"b5":7,"b6":6,"b7":7,"b8":4,"b9":7,"c1":"Sistem mutu pekerjaan sudah terstandar, ada peluang improvisasi pekerjaan, ada peluang untuk belajar/meningkatkan kompetensi dan skill/pengembangan diri, Komunikasi antar rekan kerja terbuka, pembagian kerja di program cukup proporsional","c2":"Peran tim supporting/operasional di optimalkan/lebih gercep terutama pada hal teknis maupun administratif, update informasi terbaru diinfokan/disosialisasikan dengan segera, evaluasi dan masukan ditindaklanjuti secara proaktif","c3":"Strategi pengembangan desain program dan tata kelola SDM alumni, Asesmen/pengukuran dampak program, Analisis dan visualisasi data program, Pengembangan kelas pembelajaran digital/LMS","c4":"Komunikasi internal dan eksternal, penyesuaian desain program dengan kebutuhan PM, penyesuaian tupoksi pekerjaan dengan pelaksananya, publikasi capaian program secara masif, evaluasi dan perbaikan berkala","c5":"Proses ke SDM-an dirasa masih belum efektif tapi mungkin banyak faktor yang mempengaruhi baik internal maupun eksternal (misal: proses rekrutmen yang cukup lama, kriteria skill yang dicari kurang spesifik, SDM yang ada jika belum memenuhi kriteria dukungan pengembangan dirinya masih terbatas, untuk SDM yang dimutasi atau dipromosikan belum disiapkan secara matang penggantinya)\\nProses evaluasi juga seringkali dilakukan tapi tindak lanjut/feedbacknya kadang cukup lama/kurang optimal untuk karyawan berprestasi juga sudah mulai kurang terdengar apresiasinya.","c6":"Memastikan setiap tim bekerja sesuai tupoksinya, tidak tumpang tindih, jika memungkinkan memerlukan tim khusus lebih baik menambah dengan spesifikasi skill yang paling sesuai kebutuhan\\nMemberi ruang/memfasilitasi pengembangan diri tim yang membutuhkan dari hasil asesmen/evaluasi/training need analysis\\nAda ruang diskusi berkala atasan dan bawahan untuk mendeliver visi/misi/strategi/capaian yang diharapkan lembaga\\nTindak lanjut evaluasi secara berkala, jika ada yang kurang optimal disampaikan dan diberi masukan/solusi perbaikan/coaching. dan jika ada yang berprestasi diberikan apresiasi","b10":4,"b11":7,"b12":7,"b13":2,"b14":5,"b15":7,"b16":7,"b17":3,"b18":3,"b19":5,"b20":7,"b21":5,"b22":5,"b23":5,"b24":1,"b25":2}' WHERE id = '696b60ab-8d2b-40a7-b10c-f83888de40a4';
UPDATE employee_assessments SET answers = '{"a1":7,"a2":6,"a3":7,"a4":7,"a5":6,"b2":5,"b3":5,"b4":2,"b5":6,"b6":6,"b7":7,"b8":5,"b9":6,"c1":"Sebagai organ yang baru terbentuk,sejauh ini sudah berjalan baik koordinasi dan komunikasi antar departemen di dalamnya.","c2":"Eksistensi Teach sebagai organ baru yang mempunyai kapasitas di pengembangan Pendidikan dan Budaya","c3":"Mau pelatihan Leader tapi ga punya anak buah","c4":"Lini Komunikasi, Lini Kompetensi","c5":"Terbagi-baginya program di YPUU menjadi organ-organ menurut saya kurang efektif.","c6":"Engagement dengan seluruh Insan YPUU lebih dikuatkan kembali","b10":6,"b11":6,"b12":7,"b13":4,"b14":7,"b15":6,"b16":7,"b17":6,"b18":3,"b19":6,"b20":6,"b21":6,"b22":6,"b23":5,"b24":6,"b25":4}' WHERE id = '101856ca-81a7-49ea-b281-c1de6c5f7930';
UPDATE employee_assessments SET answers = '{"a1":5,"a2":6,"a3":7,"a4":6,"a5":5,"b2":7,"b3":6,"b4":2,"b5":6,"b6":5,"b7":6,"b8":7,"b9":6,"c1":"di TEAC9H konsep dasar penggunaan dana zakat menurut ku tapat, berusaha menyentuh banyak pihak mulai dari pemuda, guru, sekolah, dan juga penggiat literasi (masyarakat) agar dapat lebih berdaya dengan diberikannya pendidikan. Tata kelola karyawan pun sudah diupayakan dengan maksimal. lingkungan kerja menyenangkan. ","c2":"Tanggung jawab setiap individu dalam sebuah program too much. Aslinya, saya menikmati dan mencintai pekerjaan saya. Namun Banyaknya load pekerjaan membuat saya dalam waktu waktu tertentu kewalahan. Bahkan ada rasa bersalah saat di hari libur atau hari yang semestinya tidak harus saya bekerja, tapi karena banyaknya load pekerjaan, saat saya ingin fokus istirahat atau melakukan aktivitas pribadi, saya tetap merasa bersalah. Bisa kah penambahan sdm di program dilakukan ? Sebagai program officer, karena banyaknya tugas2 administrasi dalam program itu sendiri, kadang menyedot energi dan waktu untuk kami lebih inovatif dan kreatif mengembangkan substansi programnya. ","c3":"Pelatihan atau pengembangan tentu diperlukan dengan mempertimbangkan beban bekerja. jika adanya pelatihan namun waktu pelaksanaannya tetap menjadi pilihan antara ingin mengikuti pelatihan/pengembangan dengan serius atau mengerjakan kejaran pekerjaan, tentu tidak efektif. Pengembangan diri skill professional coach ","c4":"saya ingin lebih mengupayakan untuk memahami porsi kerja setiap anggota tim.  Memastikan bahwa setiap anggota dapat bekerja di ranah yang menjadi kekuatannya masing-masing, dengan porsi kerja yang tetap sehat dan tidak melampaui kapasitas dirinya dalam menangani pekerjaan.\\nSelain itu, saya juga ingin mengupayakan lingkungan kerja yang mampu saling menguatkan motivasi internal setiap anggota, sehingga mereka tidak hanya bekerja karena tuntutan, tetapi juga merasa berkembang dan dihargai dalam prosesnya.","c5":"Banyaknya tugas administratif yang harus dilakukan oleh tim program ditengah waktu yang terbatas dan kebutuhan kami untuk terus mengelola program agar bermanfaat, dan kontekstual","c6":"Perbanyak ruang ruang reflektif kelompok. ","b10":5,"b11":6,"b12":4,"b13":7,"b14":4,"b15":6,"b16":7,"b17":4,"b18":7,"b19":6,"b20":5,"b21":5,"b22":6,"b23":6,"b24":5,"b25":3}' WHERE id = '8de77ba9-e072-4ca8-8472-66d4ab5aeec8';
UPDATE employee_assessments SET answers = '{"a1":6,"a2":7,"a3":6,"a4":6,"a5":5,"b2":7,"b3":3,"b4":2,"b5":6,"b6":5,"b7":5,"b8":5,"b9":5,"c1":"Kerekatan karyawan semakin membaik dibanding sebelumnya, pola komunikasi kepala organ sebagai pucuk pimpinan sudah sangat baik, namun beberapa keputusan tegas terhadap beberapa karyawan yg memang perlu di \"tindak\" masih belum terasa hehe\n","c2":"Manajemen komunikasi kepala departemen ke staff/koordinator di bawahnya, sangat perlu untuk diperbaiki","c3":"Kalau secara pribadi sih butuh ngembangin skill fullstack developer dan data analis, selain sebagai skills teknis jg perlu belajar manajemen framewok thinking. agar bisa memberikan advice kepada orang lain. Kalau untuk tim, sebaiknya banyakin pelatihan bonding agar benar2 bisa semakin rekat","c4":"kalau pimpinan yang di maksud adalah memiliki bawahan misal staff sebagai supervisor/manajer maka hal yang paling penting diperbaiki sikap taktis dan adaptif. bisa menyesuaikan ritme-ritme baik yg sudah ada sebelumnya, dan memperbaiki ritme-ritme kurang baik yang sebelumnya terjadi","c5":"Proses pengambilan kebijakan oleh PENGURUS YPUU, indikasi yg terasa adalah kurang eratnya pra pengurus terhadap karyawan lain yg di bawahnya. sering kali mengambil keputusan sepihak dan mengorbankan banyak target tanpa memberikan langkah backup yg strategis. Contoh pembentukan panitia kurban yg terkesan tanpa persiapan, hanya main aman dan memberikan wejangan imbalan surgawi, ya kita sebagai muslim tau imbalan setiap kebaikan adalah kebaikan yg berlimpah tapi jadi beban pekerjaan di luar tanggung jawab pekerjaan utama, RDP juga sama, Ramadan jg begitu. Satu lagi soal proses delivery SKI yang sampai hari ini saya bekerja masih belum mendapat SKI yg jelas padahal udah sangat banyak yg di kerjakan dan mungkin melebihi target dan sepengelaman saya kalau outstanding ga pernah dapat reward...","c6":"Satu Gedung Kerja. ini penting jangan sampai terpisah2 kita sulit kordinasi taktis dan HC pun jg sulit membuat event internal tim jika tempat kerja saja udah beda gedung, Misal saya punya ide untuk memberikan reward employee of the month salah satu kategorinya adalah\"Si Paling Rajin Absensi bulan ini\" ketika di umumkan di mading gedung jadi cukup bikin 1 pengumuman aja, atau misal \"Si Paling Rajin Sedekah Makanan\" kita pun cukup bikin 1 pemenang di satu gedung kan enak jadinya","b10":3,"b11":7,"b12":4,"b13":2,"b14":2,"b15":4,"b16":5,"b17":2,"b18":4,"b19":6,"b20":7,"b21":5,"b22":4,"b23":2,"b24":2,"b25":3}' WHERE id = 'f09f0bf5-9776-4263-9c31-12de596e9847';
UPDATE employee_assessments SET answers = '{"a1":5,"a2":7,"a3":5,"a4":7,"a5":7,"b2":6,"b3":6,"b4":5,"b5":7,"b6":7,"b7":6,"b8":7,"b9":6,"c1":"1. Sudah menjadi organ tersendiri, artinya pengelolaan dan jangkauan program bisa lebih mendalam lagi.\\n2. Setidaknya perangkat untuk menjadi organ secara mandiri sudah ada, walau memang beberapa bagian belum optimal\\n3. Walau organ baru, tetapi sudah memiliki sistem yang sebelumnya dipakai oleh LPI","c2":"1. Tata kelola organisasi. Sebagai organ sudah tentu memiliki tata kelolanya sendiri yang dapat dikembangkan sesuai kebutuhan\\n2. Alur koordinasi dan pelaporan. Tidak ada mekanisme pengecekan terhadap capaian yang sudah dilakukan\\n3. Ke-SDM-an. Perlu sekiranya dipikirkan mendalam tentang tata kelola SDM. Supaya lebih berimbang dan lebih berkeadilan\\n4. Jika memang, fokus pada bagian campign program maka seharusnya saat ini sudah mulai nampak perubahannya.","c3":"1. Changes Management \\n2. Publikasi riset program\\n3. MEAL PLAN","c4":"1. Membuka ruang tumbuh untuk seluruh insan\\n2. Membangun bounding tim\\n3. Menguatkan visi dan misi organ\\n4. Interkoneksi antar bagian\\n5. Ekspansi program untuk dapat lebih berdampak","c5":"1. Proses administrasi yang lama.\\n2. Pelaporan pencapaian program yang tidak terkontrol\\n3. Banyaknya unit program yang ada, sehingga tidak fokus dan sulit dipahami eksternal\\n","c6":"Sejauh ini belum ada.\\nSudah baik upaya2 yang dilakukan untuk merekatkan tim.","b10":7,"b11":6,"b12":6,"b13":6,"b14":6,"b15":6,"b16":6,"b17":5,"b18":6,"b19":6,"b20":7,"b21":7,"b22":6,"b23":5,"b24":5,"b25":6}' WHERE id = 'f7113003-d18c-40e7-be5d-d039bca85e0f';